  "PAPAL ARMS BAN AGAINST {0}: OBSERVED BY {1}": "EMBARGO PAPAL DE ARMAS CONTRA {0}: OBSERVADO POR {1}",
  "PAPAL ARMS BAN AGAINST {0}: OBSERVED BY {1} POLITIES": "EMBARGO PAPAL DE ARMAS CONTRA {0}: RESPEITADO POR {1} ESTADOS",
